/** Rychlé vyhledání tahu podle id. */
const MOVES_BY_ID = new Map(MOVES.map((m) => [m.id, m]));

/**
 * Vrátí definici tahu podle id (nebo undefined).
 * @param {string} id
 * @returns {Move | undefined}
 */
export function getMove(id) {
  return MOVES_BY_ID.get(id);
}
